BEGIN;
CREATE TABLE IF NOT EXISTS companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_code varchar(50) NOT NULL UNIQUE, company_name varchar(255) NOT NULL, industry varchar(100), entity_type varchar(50), tax_id_encrypted text, country_code char(2), base_currency char(3) NOT NULL DEFAULT 'USD', fiscal_year_start_month smallint NOT NULL DEFAULT 1 CHECK(fiscal_year_start_month BETWEEN 1 AND 12), reporting_framework varchar(20) NOT NULL DEFAULT 'GAAP' CHECK(reporting_framework IN ('GAAP','IFRS','OTHER')), address jsonb NOT NULL DEFAULT '{}'::jsonb, contact_info jsonb NOT NULL DEFAULT '{}'::jsonb, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','ARCHIVED')), created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), parent_entity_id uuid REFERENCES entities(id), entity_code varchar(50) NOT NULL, entity_name varchar(255) NOT NULL, ownership_percentage numeric(7,4) CHECK(ownership_percentage BETWEEN 0 AND 100), country_code char(2), functional_currency char(3) NOT NULL, reporting_currency char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,entity_code));
CREATE TABLE IF NOT EXISTS accounting_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES entities(id), period_name varchar(40) NOT NULL, start_date date NOT NULL, end_date date NOT NULL, status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED','LOCKED')), closed_by uuid REFERENCES users(id), closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(start_date <= end_date), UNIQUE(entity_id,start_date,end_date));
CREATE INDEX IF NOT EXISTS ix_entities_company_parent ON entities(company_id,parent_entity_id);
COMMIT;
